package cn.sifangguan.hotelaios.finance;
import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.AccessPolicy;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

@Service @Transactional
public class FinanceMigrationService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;private final FinanceAccountingService accounting;
 private static final Set<String> KINDS=Set.of("OPENING","OPEN_ITEM","ASSET","INVENTORY","PREPAID");
 private static final Set<String> FIELDS=Set.of("sourceKey","accountCode","accumulatedAccountCode","physicalAssetId","inventoryItemId","inServiceDate","originalUsefulMonths","name","direction","businessDate","dueDate","partyName","employeeReference","debit","credit","originalAmount","remainingAmount","accumulatedAmount","quantity","unit","residualAmount","remainingMonths","benefitEnd");
 public FinanceMigrationService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit,FinanceAccountingService accounting){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;this.accounting=accounting;}
 private TenantPrincipal prepare(){access.requirePermission("finance.configure");var p=access.principal();database.apply(p.tenantId());return p;}
 private Map<String,Object> book(TenantPrincipal p,UUID id){var rows=jdbc.queryForList("select * from fa_book where tenant_id=:tenant and id=:book",base(p).addValue("book",id));if(rows.isEmpty())throw missing();access.requireOrgScope(FinanceV2Support.id(rows.getFirst().get("hotel_id")));return rows.getFirst();}
 public Map<String,Object> templates(){prepare();return Map.of("adapter","KINGDEE_CONFIGURABLE_EXPORT_MAPPING","formats",List.of("csv","xlsx"),"kinds",KINDS,"fields",new TreeSet<>(FIELDS),"required",Map.of("OPENING",List.of("accountCode","debit","credit"),"OPEN_ITEM",List.of("sourceKey","accountCode","name","direction","businessDate","dueDate","partyName","originalAmount","remainingAmount"),"ASSET",List.of("sourceKey","accountCode","name","direction","businessDate","originalAmount","remainingAmount","accumulatedAmount","residualAmount","remainingMonths","accumulatedAccountCode","physicalAssetId","inServiceDate","originalUsefulMonths"),"INVENTORY",List.of("sourceKey","accountCode","name","direction","businessDate","originalAmount","remainingAmount","quantity","unit","inventoryItemId"),"PREPAID",List.of("sourceKey","accountCode","name","direction","businessDate","originalAmount","remainingAmount","remainingMonths","benefitEnd")),"status","FILE_IMPORT_AVAILABLE_API_NOT_CONFIGURED","notes",List.of("适配真实导出列而非猜测金蝶账套编号；每种子账一批，表头映射保留在批次","科目期初正式导入后不可撤销；子账先暂存，对账通过才能激活","不会修改已有库存实物数量；迁移财务期初须与既有实物来源核对"));}
 public Map<String,Object> columns(String name,byte[] bytes){prepare();if(bytes.length==0||bytes.length>20*1024*1024)throw bad("文件为空或超过20MB");var rows=name!=null&&name.toLowerCase(Locale.ROOT).endsWith(".csv")?FinanceMigrationParser.csv(bytes):name!=null&&name.toLowerCase(Locale.ROOT).endsWith(".xlsx")?FinanceMigrationParser.xlsx(bytes):null;if(rows==null||rows.isEmpty())throw bad("只支持CSV/XLSX实际导出文件");return Map.of("columns",rows.getFirst(),"dataRows",Math.max(0,rows.size()-1));}
 public Map<String,Object> batches(UUID book){var p=prepare();if(book!=null)book(p,book);return output(Map.of("items",jdbc.queryForList("select b.* from fm_batch b join fa_book k on k.tenant_id=b.tenant_id and k.id=b.book_id where b.tenant_id=:tenant and (:tenantScope or k.hotel_id in (:scopes)) and (cast(:book as uuid) is null or b.book_id=:book) order by b.created_at desc limit 200",base(p).addValue("book",book))));}
 public Map<String,Object> preview(UUID request,UUID bookId,String kind,String source,String filename,byte[] bytes,Map<String,String> mapping){var p=prepare();var book=book(p,bookId);if(!KINDS.contains(kind))throw bad("未知迁移子账类型");if(source==null||source.isBlank()||source.length()>500)throw bad("需填写真实源系统、导出账套和核对依据");if(filename==null||filename.length()>240||mapping.isEmpty()||!FIELDS.containsAll(mapping.keySet()))throw bad("文件名或字段映射无效");String hash=FinanceService.hash(bytes);var b=base(p).addValue("id",request);var old=jdbc.queryForList("select * from fm_batch where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("file_sha256"))||!bookId.equals(id(old.getFirst().get("book_id")))||!kind.equals(old.getFirst().get("kind"))||!json(new TreeMap<>(mapping)).equals(json(new TreeMap<>(map(old.getFirst().get("mapping"))))))throw conflict("预览请求编号用于不同文件或映射");return detail(request);}var parsed=FinanceMigrationParser.parse(filename,bytes,mapping);var normalized=new ArrayList<Map<String,Object>>();var seen=new HashSet<String>();int index=0;
  for(var row:parsed){int line=Integer.parseInt(row.remove("_row"));var errors=new ArrayList<String>();var values=new LinkedHashMap<String,Object>();for(var e:row.entrySet())values.put(e.getKey(),e.getValue());for(var bound:Map.of("accountCode",32,"accumulatedAccountCode",32,"name",240,"partyName",160,"employeeReference",160,"unit",40).entrySet())if(row.getOrDefault(bound.getKey(),"").length()>bound.getValue())errors.add("字段超过允许长度："+bound.getKey());String key=kind.equals("OPENING")?row.getOrDefault("accountCode",""):row.getOrDefault("sourceKey","");if(key.isBlank()||key.length()>160||!seen.add(key))errors.add("来源唯一号为空、过长或批内重复");String account=row.getOrDefault("accountCode","");if(jdbc.queryForObject("select count(*) from fa_account where tenant_id=:tenant and book_id=:book and code=:code and enabled",base(p).addValue("book",bookId).addValue("code",account),Integer.class)!=1)errors.add("控制科目不存在或未启用");
   if(kind.equals("OPENING")){BigDecimal debit=decimal(row,"debit",2,errors),credit=decimal(row,"credit",2,errors);if(debit.signum()>0&&credit.signum()>0)errors.add("同科目期初不能同时有借和贷");values.put("debit",debit.toPlainString());values.put("credit",credit.toPlainString());}
   else {required(row,"name",errors);required(row,"direction",errors);if(!Set.of("DEBIT","CREDIT").contains(row.getOrDefault("direction","")))errors.add("方向必须为DEBIT或CREDIT");LocalDate business=day(row,"businessDate",errors);if(business!=null&&!business.isBefore(((java.sql.Date)book.get("start_month")).toLocalDate()))errors.add("期初子账业务日必须早于账套启用日");if(row.containsKey("dueDate")&&!row.get("dueDate").isBlank())day(row,"dueDate",errors);BigDecimal original=decimal(row,"originalAmount",2,errors),remaining=decimal(row,"remainingAmount",2,errors);if(remaining.compareTo(original)>0)errors.add("剩余金额超过原始金额");values.put("originalAmount",original.toPlainString());values.put("remainingAmount",remaining.toPlainString());if(kind.equals("OPEN_ITEM")){required(row,"partyName",errors);day(row,"dueDate",errors);}if(kind.equals("ASSET")){BigDecimal accumulated=decimal(row,"accumulatedAmount",2,errors),residual=decimal(row,"residualAmount",2,errors);if(original.subtract(accumulated).compareTo(remaining)!=0||residual.compareTo(remaining)>0)errors.add("资产原值减累计折旧不等于净值或残值超过净值");values.put("accumulatedAmount",accumulated.toPlainString());values.put("residualAmount",residual.toPlainString());if(!(remaining.compareTo(residual)==0&&"0".equals(row.get("remainingMonths"))))positiveInt(row,"remainingMonths",errors);positiveInt(row,"originalUsefulMonths",errors);if(original.signum()<=0)errors.add("固定资产原值须大于零");LocalDate service=day(row,"inServiceDate",errors);if(!"DEBIT".equals(row.get("direction")))errors.add("固定资产原值必须为借方");if(service!=null&&service.isAfter(((java.sql.Date)book.get("start_month")).toLocalDate()))errors.add("期初资产原投用日不能晚于启用期");try{if(Integer.parseInt(row.getOrDefault("remainingMonths","0"))>Integer.parseInt(row.getOrDefault("originalUsefulMonths","0")))errors.add("剩余寿命超过原预计使用寿命");}catch(NumberFormatException ignored){}String contra=row.getOrDefault("accumulatedAccountCode","");if(account.equals(contra))errors.add("资产原值与累计折旧必须显式映射不同科目");if(jdbc.queryForObject("select count(*) from fa_account where tenant_id=:tenant and book_id=:book and code=:code and enabled",base(p).addValue("book",bookId).addValue("code",contra),Integer.class)!=1)errors.add("累计折旧控制科目不存在或未启用");try{UUID physical=UUID.fromString(row.getOrDefault("physicalAssetId",""));if(jdbc.queryForObject("select count(*) from store_fixed_asset where tenant_id=:tenant and id=:asset and hotel_org_unit_id=:hotel",base(p).addValue("asset",physical).addValue("hotel",book.get("hotel_id")),Integer.class)!=1)errors.add("实物资产不属于当前主体门店");}catch(IllegalArgumentException e){errors.add("需显式映射有效中台实物资产ID，不按名字猜测");}}if(kind.equals("PREPAID")){positiveInt(row,"remainingMonths",errors);LocalDate end=day(row,"benefitEnd",errors);if(end!=null&&end.isBefore(((java.sql.Date)book.get("start_month")).toLocalDate()))errors.add("待摊受益结束日早于启用期");}if(kind.equals("INVENTORY")){BigDecimal quantity=decimal(row,"quantity",4,errors);if(quantity.signum()==0&&remaining.signum()>0)errors.add("零数量不能承载正存货价值");required(row,"unit",errors);values.put("quantity",quantity.toPlainString());try{UUID item=UUID.fromString(row.getOrDefault("inventoryItemId",""));var existing=jdbc.queryForList("select i.unit,b.quantity from store_resource_item i left join store_inventory_balance b on b.tenant_id=i.tenant_id and b.item_id=i.id where i.tenant_id=:tenant and i.id=:item and i.hotel_org_unit_id=:hotel and i.status=\'ACTIVE\'",base(p).addValue("item",item).addValue("hotel",book.get("hotel_id")));if(existing.isEmpty()||!Objects.equals(existing.getFirst().get("unit"),row.get("unit"))||amount(existing.getFirst().get("quantity")).compareTo(quantity)!=0)errors.add("存货实物映射、基本单位或当前数量不一致，请先核对库存");}catch(IllegalArgumentException e){errors.add("必须显式映射本店实物品目ID，不按名称新建库存");}}}
   normalized.add(Map.of("line",line,"sourceKey",key,"values",values,"errors",errors));if(++index>10000)throw bad("单批最多10000行");}
  if(normalized.isEmpty())throw bad("文件没有可预览的数据行");b.addValue("book",bookId).addValue("kind",kind).addValue("name",filename).addValue("source",source).addValue("hash",hash).addValue("mapping",json(new TreeMap<>(mapping)));jdbc.update("insert into fm_batch(id,tenant_id,book_id,kind,original_name,source_reference,file_sha256,mapping,created_by) values(:id,:tenant,:book,:kind,:name,:source,:hash,cast(:mapping as jsonb),:actor)",b);jdbc.update("insert into fm_sourcefile(tenant_id,batch_id,file_bytes) values(:tenant,:id,:bytes)",base(p).addValue("id",request).addValue("bytes",bytes));for(var row:normalized)jdbc.update("insert into fm_row(tenant_id,batch_id,row_no,source_key,values,errors) values(:tenant,:id,:line,:key,cast(:values as jsonb),cast(:errors as jsonb))",base(p).addValue("id",request).addValue("line",row.get("line")).addValue("key",row.get("sourceKey")).addValue("values",json(row.get("values"))).addValue("errors",json(row.get("errors"))));audit.record("FINANCE_MIGRATION_PREVIEWED","FM_BATCH",request,json(Map.of("sha256",hash,"rows",normalized.size(),"kind",kind)));return detail(request);
 }
 public Map<String,Object> detail(UUID id){var p=prepare();var batch=batch(p,id,false);var result=new LinkedHashMap<>(batch);result.put("rows",jdbc.queryForList("select row_no,source_key,values,errors from fm_row where tenant_id=:tenant and batch_id=:id order by row_no",base(p).addValue("id",id)));result.put("errorCount",jdbc.queryForObject("select count(*) from fm_row where tenant_id=:tenant and batch_id=:id and errors<>'[]'::jsonb",base(p).addValue("id",id),Integer.class));result.put("reconciliation",reconciliation(p,batch));return output(result);}
 public FinanceAccountingService.ExportFile original(UUID id){var p=prepare();var batch=batch(p,id,false);byte[] bytes=jdbc.queryForObject("select file_bytes from fm_sourcefile where tenant_id=:tenant and batch_id=:id",base(p).addValue("id",id),byte[].class);if(bytes==null||!FinanceService.hash(bytes).equals(batch.get("file_sha256")))throw conflict("源文件校验未通过，已停止下载");String name=batch.get("original_name").toString();audit.record("FINANCE_MIGRATION_ORIGINAL_READ","FM_BATCH",id,json(Map.of("sha256",batch.get("file_sha256"))));return new FinanceAccountingService.ExportFile(name,name.toLowerCase(Locale.ROOT).endsWith(".csv")?"text/csv;charset=utf-8":"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",bytes,batch.get("file_sha256").toString());}
 private Map<String,Object> batch(TenantPrincipal p,UUID id,boolean lock){var rows=jdbc.queryForList("select * from fm_batch where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(rows.isEmpty())throw missing();book(p,FinanceV2Support.id(rows.getFirst().get("book_id")));return rows.getFirst();}
 public Map<String,Object> commit(UUID id,FinanceMigrationModels.Command in){var p=prepare();var batch=batch(p,id,true);if(!in.expectedFileHash().equals(batch.get("file_sha256")))throw conflict("源文件哈希与预览不一致");if(Set.of("STAGED","ACTIVE").contains(batch.get("status")))return detail(id);check(batch,in);if(!"PREVIEW".equals(batch.get("status")))throw conflict("该批次不可提交，请重新预览");var b=base(p).addValue("id",id).addValue("book",batch.get("book_id"));jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,0))",base(p).addValue("key",p.tenantId()+":migration:"+batch.get("book_id")),Object.class);var rows=jdbc.queryForList("select * from fm_row where tenant_id=:tenant and batch_id=:id order by row_no",b);if(rows.stream().anyMatch(r->!"[]".equals(r.get("errors").toString())))throw conflict("预览存在错误，整批未导入；请修正源文件后新建批次");
  if("OPENING".equals(batch.get("kind"))){var balances=new ArrayList<FinanceAccountingModels.Opening>();for(var row:rows){var v=map(row.get("values"));balances.add(new FinanceAccountingModels.Opening(v.get("accountCode").toString(),amount(v.get("debit")),amount(v.get("credit"))));}accounting.imports(new FinanceAccountingModels.Import(id,FinanceV2Support.id(batch.get("book_id")),"COMMIT",batch.get("source_reference").toString().substring(0,Math.min(160,batch.get("source_reference").toString().length())),balances,Map.of("fileSha256",batch.get("file_sha256").toString(),"confirmation",in.confirmationNote())));jdbc.update("update fm_batch set status='ACTIVE',version=version+1,committed_at=now(),activated_at=now() where tenant_id=:tenant and id=:id",b);}
  else {for(var row:rows){var v=map(row.get("values"));var source=base(p).addValue("book",batch.get("book_id")).addValue("kind",batch.get("kind")).addValue("key",row.get("source_key"));if(jdbc.queryForObject("select count(*) from fm_subledger where tenant_id=:tenant and book_id=:book and kind=:kind and source_key=:key and status<>'CANCELLED'",source,Integer.class)>0)throw conflict("同源子账已经暂存或激活，整批未导入；先核对原批次");source.addValue("id",UUID.randomUUID()).addValue("batch",id).addValue("code",v.get("accountCode")).addValue("name",v.get("name")).addValue("contra",v.get("accumulatedAccountCode")).addValue("physical",v.get("physicalAssetId")==null?null:UUID.fromString(v.get("physicalAssetId").toString())).addValue("item",v.get("inventoryItemId")==null?null:UUID.fromString(v.get("inventoryItemId").toString())).addValue("service",optionalDate(v.get("inServiceDate"))).addValue("life",v.get("originalUsefulMonths")==null?null:Integer.parseInt(v.get("originalUsefulMonths").toString())).addValue("direction",v.get("direction")).addValue("day",LocalDate.parse(v.get("businessDate").toString())).addValue("due",optionalDate(v.get("dueDate"))).addValue("party",v.get("partyName")).addValue("employee",v.get("employeeReference")).addValue("original",amount(v.get("originalAmount"))).addValue("remaining",amount(v.get("remainingAmount"))).addValue("accumulated",amount(v.get("accumulatedAmount"))).addValue("quantity",v.get("quantity")==null?null:amount(v.get("quantity"))).addValue("unit",v.get("unit")).addValue("residual",v.get("residualAmount")==null?null:amount(v.get("residualAmount"))).addValue("months",v.get("remainingMonths")==null?null:Integer.parseInt(v.get("remainingMonths").toString())).addValue("end",optionalDate(v.get("benefitEnd")));jdbc.update("insert into fm_subledger(id,tenant_id,book_id,batch_id,kind,source_key,account_code,accumulated_account_code,physical_asset_id,inventory_item_id,in_service_date,original_useful_months,name,direction,business_date,due_date,party_name,employee_reference,original_amount,remaining_amount,accumulated_amount,quantity,unit,residual_amount,remaining_months,benefit_end) values(:id,:tenant,:book,:batch,:kind,:key,:code,:contra,:physical,:item,:service,:life,:name,:direction,:day,:due,:party,:employee,:original,:remaining,:accumulated,:quantity,:unit,:residual,:months,:end)",source);}jdbc.update("update fm_batch set status='STAGED',version=version+1,committed_at=now() where tenant_id=:tenant and id=:id",b);}
  audit.record("FINANCE_MIGRATION_COMMITTED","FM_BATCH",id,json(in));return detail(id);
 }
 public Map<String,Object> transition(UUID id,FinanceMigrationModels.Command in,boolean activate){var p=prepare();var batch=batch(p,id,true);check(batch,in);if(activate&&"ACTIVE".equals(batch.get("status"))||!activate&&"CANCELLED".equals(batch.get("status")))return detail(id);if(!"STAGED".equals(batch.get("status"))&&!(!activate&&"PREVIEW".equals(batch.get("status"))))throw conflict("仅未生效批次可撤销；科目期初及已激活子账须走正式调整，不得删改历史");if(activate&&!Boolean.TRUE.equals(reconciliation(p,batch).get("matched")))throw conflict("子账与期初控制科目未核对一致，不能激活");var b=base(p).addValue("id",id).addValue("status",activate?"ACTIVE":"CANCELLED");jdbc.update("update fm_subledger set status=:status where tenant_id=:tenant and batch_id=:id",b);jdbc.update("update fm_batch set status=:status,version=version+1,activated_at=case when :status='ACTIVE' then now() else activated_at end where tenant_id=:tenant and id=:id",b);audit.record(activate?"FINANCE_MIGRATION_ACTIVATED":"FINANCE_MIGRATION_CANCELLED","FM_BATCH",id,json(in));return detail(id);}
 public Map<String,Object> subledger(UUID bookId,String kind){var p=prepare();book(p,bookId);if(!KINDS.contains(kind)||kind.equals("OPENING"))throw bad("未知期初子账类型");return output(Map.of("items",jdbc.queryForList("select * from fm_subledger where tenant_id=:tenant and book_id=:book and kind=:kind and status='ACTIVE' order by source_key",base(p).addValue("book",bookId).addValue("kind",kind)),"basis","CONFIRMED_OPENING_NOT_NEW_EXPENSE_OR_PHYSICAL_STOCK_MOVEMENT"));}
 private Map<String,Object> reconciliation(TenantPrincipal p,Map<String,Object> batch){UUID book=id(batch.get("book_id"));var b=base(p).addValue("book",book).addValue("kind",batch.get("kind")).addValue("batch",batch.get("id"));boolean opening=jdbc.queryForObject("select count(*) from fa_import_batch where tenant_id=:tenant and book_id=:book",b,Integer.class)==1;var rows=jdbc.queryForList("""
   with controlled as (
    select s.account_code,case when s.kind='ASSET' then s.original_amount when s.direction='DEBIT' then s.remaining_amount else -s.remaining_amount end as amount
     from fm_subledger s where s.tenant_id=:tenant and s.book_id=:book and s.kind=:kind and (s.status='ACTIVE' or s.batch_id=:batch and s.status='STAGED')
    union all select s.accumulated_account_code,-s.accumulated_amount from fm_subledger s
     where s.tenant_id=:tenant and s.book_id=:book and s.kind=:kind and s.kind='ASSET' and (s.status='ACTIVE' or s.batch_id=:batch and s.status='STAGED')
   )
   select c.account_code,sum(c.amount) as subledger_net,coalesce(max(o.debit-o.credit),0) as opening_net
    from controlled c left join fa_account a on a.tenant_id=:tenant and a.book_id=:book and a.code=c.account_code
    left join fa_opening_balance o on o.tenant_id=a.tenant_id and o.account_id=a.id group by c.account_code order by c.account_code
   """,b);boolean matched=opening&&!rows.isEmpty()&&rows.stream().allMatch(r->amount(r.get("subledger_net")).compareTo(amount(r.get("opening_net")))==0);return output(Map.of("openingConfirmed",opening,"matched",matched,"lines",rows,"interpretation","各类子账按控制科目汇总，与启用期科目余额逐项核对；无期初或金额不符不得激活。资产原值和累计折旧分别核对显式科目，净值另作原值减累计折旧校验。"));}
 private void check(Map<String,Object> batch,FinanceMigrationModels.Command in){version(batch,in.expectedVersion());if(!in.expectedFileHash().equals(batch.get("file_sha256")))throw conflict("源文件哈希与预览不一致");}
 private static LocalDate optionalDate(Object value){return value==null||value.toString().isBlank()?null:LocalDate.parse(value.toString());}
 private static void required(Map<String,String> row,String key,List<String> errors){if(row.getOrDefault(key,"").isBlank())errors.add("必填字段缺失："+key);}
 private static BigDecimal decimal(Map<String,String> row,String key,int scale,List<String> errors){try{String s=row.getOrDefault(key,"");if(!s.matches("\\d{1,16}(\\.\\d{1,"+scale+"})?"))throw new IllegalArgumentException();return new BigDecimal(s).setScale(scale);}catch(Exception e){errors.add("金额/数量格式无效或负数："+key);return BigDecimal.ZERO.setScale(scale);}}
 private static LocalDate day(Map<String,String> row,String key,List<String> errors){try{return LocalDate.parse(row.getOrDefault(key,""));}catch(Exception e){errors.add("日期必须为YYYY-MM-DD："+key);return null;}}
 private static void positiveInt(Map<String,String> row,String key,List<String> errors){try{int v=Integer.parseInt(row.getOrDefault(key,""));if(v<1||v>1200)throw new IllegalArgumentException();}catch(Exception e){errors.add("剩余月数须为1到1200："+key);}}
}
